/**
 * The walk kit (punch list #142): the rows a session makes to run the Messages loop on prod end to end, on the company's
 * own inbox and number. `walk_setup` writes them to `app_settings` `walk_kit_v1` (`to-dos/walk-kit/README.md`), and
 * this reads them back for the two readers' rule (decision 4): an address or number of our own (`messages/ownChannels.ts`)
 * is taken as a person only when the kit's contact carries it; otherwise it is left out, as it always was. The rule is
 * dormant while no kit exists, and it can never misfile real mail: a real customer's record that carries bids@ is not
 * the kit's. Pure, mirrored to the edge by `scripts/edge-kernels.mjs`.
 */
import { isOwnNumber, type OwnChannels } from '../messages/ownChannels.ts'

/** The `app_settings` key `walk_setup` writes and `walk_cleanup` removes. */
export const WALK_KIT_KEY = 'walk_kit_v1'

/** The kit as `walk_setup` answers it. */
export interface WalkKit {
  customerId: string
  contactId: string
  emailChannelId: string | null
  phoneChannelId: string | null
  estimateId: string | null
  /** The kit's address: the bids box's. */
  email: string
  /** The kit's number: the bids box's, or the owner's own in the fallback walk. */
  phone: string | null
  testerId: string | null
  /** The fallback walk: the kit's number is one a real contact carries too, so cleanup leaves that contact's channel. */
  sharedPhone: boolean
  /** ISO. */
  madeAt: string | null
}

const text = (v: unknown): string | null => (typeof v === 'string' && v.trim() ? v.trim() : null)

/**
 * The kit from the row's `value_text`: null for no row, no JSON, or a row without the contact, the customer and the
 * address it needs.
 */
export function parseWalkKit(valueText: string | null | undefined): WalkKit | null {
  if (!valueText?.trim()) return null
  let json: unknown
  try {
    json = JSON.parse(valueText)
  } catch {
    return null
  }
  if (!json || typeof json !== 'object' || Array.isArray(json)) return null
  const o = json as Record<string, unknown>
  const customerId = text(o.customerId)
  const contactId = text(o.contactId)
  const email = text(o.email)
  if (!customerId || !contactId || !email) return null
  return {
    customerId,
    contactId,
    emailChannelId: text(o.emailChannelId),
    phoneChannelId: text(o.phoneChannelId),
    estimateId: text(o.estimateId),
    email,
    phone: text(o.phone),
    testerId: text(o.testerId),
    sharedPhone: o.sharedPhone === true,
    madeAt: text(o.madeAt),
  }
}

/**
 * A channel's key, as `public.contact_channel_key` makes it (`20261012010000_messages_spine.sql`): a number is its
 * digits, a leading 1 dropped from eleven, and nothing under seven; an address is lower-cased and trimmed, and nothing
 * without an @. The same key means the same channel.
 */
export function channelKey(kind: 'email' | 'phone', value: string | null | undefined): string {
  if (kind === 'phone') {
    const digits = (value ?? '').replace(/\D/g, '')
    const d = digits.length === 11 && digits.startsWith('1') ? digits.slice(1) : digits
    return d.length >= 7 ? d : ''
  }
  const e = (value ?? '').trim().toLowerCase()
  return e.includes('@') ? e : ''
}

/** Whether the kit's contact carries this address or number: the same key as the database's. No kit carries nothing. */
export function kitCarries(kit: WalkKit | null, kind: 'email' | 'phone', value: string): boolean {
  if (!kit) return false
  const key = channelKey(kind, value)
  if (!key) return false
  return key === channelKey(kind, kind === 'email' ? kit.email : kit.phone)
}

/**
 * What `quo-webhook` does with a number an event is about: a number that is not ours is placed as always; one of ours is
 * placed only when the kit carries it, and skipped otherwise, so a text between two of our own numbers never makes a
 * Who is this? row.
 */
export function numberPlan(number: string, own: OwnChannels, kit: WalkKit | null): 'place' | 'skip' {
  if (!isOwnNumber(own, number)) return 'place'
  return kitCarries(kit, 'phone', number) ? 'place' : 'skip'
}
